28: const $=id=>document.getElementById(id), maxHeat=100, orderLifetime=75;
29: const properties=[{name:'The Fern Flat',stage:'SAFEHOUSE · EAST WARD',label:'HOME · BACK ROOM',slots:3,next:'Garage',price:650},{name:'Marlow’s Garage',stage:'GARAGE · RAIL DISTRICT',label:'GARAGE · THE WORKSHOP',slots:5,next:'Basement lab',price:1900},{name:'The Blue Room',stage:'BASEMENT · OLD TOWN',label:'HIDDEN ROOM · LOWER LEVEL',slots:7,next:'Warehouse',price:5200},{name:'Holloway Works',stage:'WAREHOUSE · RIVERFRONT',label:'INDUSTRIAL · BAY 04',slots:10,next:'Second property',price:12000},{name:'The Long Game',stage:'MULTIPLE SITES · CITYWIDE',label:'EMPIRE · HEADQUARTERS',slots:13,next:'Empire',price:30000},{name:'Green Empire',stage:'THE EMPIRE · EVERYWHERE',label:'THE EMPIRE · HQ',slots:18,next:'—',price:0}];
30: const upgrades={room:[{id:'lamp',icon:'💡',name:'Full-spectrum lamp',desc:'+15% faster growing',cost:120},{id:'soil',icon:'🪴',name:'Living soil',desc:'+12 quality per harvest',cost:190},{id:'shelf',icon:'🧰',name:'Wall rack',desc:'+2 grow spaces',cost:320}],crew:[{id:'helper',icon:'🧑‍🌾',name:'Hire June',desc:'A steady hand · +1 space',cost:420},{id:'runner',icon:'🚲',name:'Hire Pip',desc:'Keeps orders moving',cost:780},{id:'manager',icon:'🧥',name:'Hire Sol',desc:'A calm head · sales bonus',cost:1800}],front:[{id:'laundry',icon:'🧺',name:'Wash & Fold',desc:'Legitimate front · passive income',cost:550},{id:'ledger',icon:'📒',name:'Clean books',desc:'Lower attention from sales',cost:900},{id:'sign',icon:'🪧',name:'Local favorite',desc:'Better customer offers',cost:1400}]};
31: let state=load()||{cash:180,heat:4,day:1,rep:0,plants:[],stock:0,quality:0,stage:0,upgrades:[],crew:[],fronts:[],tab:'room',mission:0,order:null,orderAge:0,actions:0,frontTime:0};state.frontTime=state.frontTime||0;state.orderAge=state.orderAge||0;
32: const missions=[{title:'A Quiet Arrangement',text:'Your upstairs neighbor, June, knows a thing or two about plants. Three cuttings, one flickering lamp, and rent due Friday. What could go wrong?',detail:'June leans against the doorframe, a paper bag of cuttings tucked under one arm. “Keep it small, keep it kind,” she says. “And don’t forget the neighbors.” You have a feeling this is only the beginning.',choices:[['Take June’s advice','June becomes a friend. +20 reputation, attention stays low.',()=>{state.rep+=20;state.heat=Math.max(0,state.heat-2)}],['Ask about bigger opportunities','A stranger called Vale is suddenly interested. +$65, +8 attention.',()=>{state.cash+=65;state.heat+=8}]]},{title:'A Favor, Not a Loan',text:'A courier with a gold tooth called Vale offers you a shortcut. He says the city is full of people who pay for discretion.',detail:'Vale slides a card across the table. “Nobody gets rich growing alone,” he says. The card has no number, only a hand-drawn moth. June says you should be careful. Both could be right.',choices:[['Take the introduction','Vale sends better customers. +$110, +12 attention.',()=>{state.cash+=110;state.heat+=12;state.rep+=8}],['Keep it neighborhood-sized','June introduces a loyal regular instead. +$55, +10 reputation.',()=>{state.cash+=55;state.rep+=10}]]},{title:'The Moth Has Two Wings',text:'Your new friend Vale has a rival: the polished, patient Lark Street Collective. Their offer is generous. Their smiles are not.',detail:'A note arrives under the door: “We can make you comfortable. Or make you a lesson.” June wants to walk away. Vale says it’s theater. Your next move will tell the neighborhood who you are.',choices:[['Meet with the Collective','A tense truce brings capital. +$220, +18 attention.',()=>{state.cash+=220;state.heat+=18}],['Stand with June','The block remembers. +30 reputation, +$90.',()=>{state.rep+=30;state.cash+=90}]]},{title:'The Long Game',text:'The little room has become a citywide operation. Sol asks w... (line truncated to 2000 chars)
33: function load(){try{return JSON.parse(localStorage.getItem('greenEmpireSave'))}catch{return null}}function save(){try{localStorage.setItem('greenEmpireSave',JSON.stringify(state));toast('Progress saved on this device.')}catch{toast('Could not save on this device.')}}function persist(){try{localStorage.setItem('greenEmpireSave',JSON.stringify(state))}catch{}}
34: function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2300)}
35: function currentOrder(){if(!state.order){const regular=Math.random()<Math.min(.55,.18+state.rep/180),need=1+(state.rep>35&&Math.random()>.72?1:0),quality=30+Math.floor(Math.random()*20);state.order={name:['Milo','Nessa','Rafi','Tess','Ollie'][Math.floor(Math.random()*5)],face:['🧢','🧣','🧑🏽‍🦱','👩🏻‍🎤','🧔🏽'][Math.floor(Math.random()*5)],need,quality,reward:Math.round((48+Math.floor(state.rep/4)+Math.floor(Math.random()*15))*(regular?1.18:1)),regular};state.orderAge=0}}
36: function level(){return properties[Math.min(state.stage,properties.length-1)]}function plantDuration(){return Math.max(12,30-(state.upgrades.includes('lamp')?7:0))}
37: function plant(){const cap=level().slots+(state.upgrades.includes('shelf')?2:0)+(state.crew.includes('helper')?1:0);if(state.plants.length>=cap){toast('No room for another cutting. Try an upgrade.');return}if(state.cash<12){toast('You need $12 for a cutting.');return}state.cash-=12;state.plants.push({progress:0,quality:48+Math.floor(Math.random()*14)});toast('Cutting planted. Keep an eye on it.');render()}
38: function harvest(){const ready=state.plants.filter(p=>p.progress>=1);if(!ready.length){toast('Nothing ready just yet. Give them a little time.');return}let q=0;ready.forEach(p=>{q+=p.quality+(state.upgrades.includes('soil')?12:0)});state.stock+=ready.length;state.quality=Math.round((state.quality*Math.max(0,state.stock-ready.length)+q)/state.stock);state.plants=state.plants.filter(p=>p.progress<1);state.actions++;toast(`${ready.length} fresh ${ready.length===1?'pack':'packs'} added to inventory.`);if(state.actions%4===0)state.day++;render()}
39: function sell(){currentOrder();const o=state.order;if(state.stock<o.need){toast('Not enough in stock for this request. Try a quick market sale or grow more.');return}if(state.quality<o.quality){toast('This customer wants better quality. Keep growing or use the market.');return}if(state.heat>=75&&Math.random()<.25){state.heat=Math.max(0,state.heat-8);toast('The handoff is delayed. Attention cools a little.');render();return}const bonus=state.upgrades.includes('manager')?Math.round(o.reward*.15):0,total=o.reward+bonus;state.stock-=o.need;state.cash+=total;state.rep+=5+(state.upgrades.includes('sign')?3:0);state.heat=Math.min(maxHeat,state.heat+(state.fronts.includes('ledger')?1:4));state.order=null;state.orderAge=0;state.day+=Math.random()>.55?1:0;toast(`Request fulfilled. +$${total} · reputation up.`);currentOrder();render();persist()}
40:  function quickSell(){if(state.stock<1){toast('No packs in stock to take to market.');return}const price=25+Math.round(state.quality*.45)+Math.floor(state.rep/12),bonus=state.upgrades.includes('manager')?Math.round(price*.15):0;state.stock--;state.cash+=price+bonus;state.heat=Math.min(maxHeat,state.heat+1);state.day+=Math.random()>.8?1:0;toast(`Market sale · 1 pack moved for $${price+bonus}.`);render();persist()}
41:  function passOrder(){state.order=null;state.orderAge=0;currentOrder();toast('You pass on that request. A new customer steps up.');render();persist()}
42: function buy(id,cost,group){if(state.upgrades.includes(id)||state.crew.includes(id)||state.fronts.includes(id))return;if(state.cash<cost){toast('Not enough cash for that yet.');return}state.cash-=cost;if(group==='crew')state.crew.push(id);else if(group==='front')state.fronts.push(id);else state.upgrades.push(id);if(id==='helper')state.rep+=5;toast('Investment made. Your operation grows.');render()}
43: function expand(){const p=properties[state.stage+1],cost=level().price;if(!p||state.cash<cost)return;state.cash-=cost;state.stage++;state.day+=3;state.heat=Math.min(maxHeat,state.heat+8);toast(`Welcome to ${p.name}. New chapter unlocked.`);render()}
